        Payload transcribed from the crsf-wg wiki page CRSF_FRAMETYPE_PARAMETER_SETTINGS_ENTRY.md
        */
        [ExtendedHeader]
        class PARAMETER_SETTINGS_ENTRY {
            // CRSF frame type byte - the source protocol's identity, not this pack's AdHoc id.
            public const int frame_type = 0x2B;
            byte fieldIndex;
            /**
            chunks still to come after this one
            */
            byte chunksRemaining;
            /**
            field index of the parent folder, 0 for top level
            */
            byte parent;
            /**
            low 7 bits: crsf_value_type; high bit: hidden
            */
            byte typeAndHidden;
            /**
            parameter name, null-terminated
            */
            [D(+56)] string label;
            /**
            current/min/max/units for numeric types, index+options for SELECT, etc.
            */
            [D(56)] byte[,,] value;
        }

        /**
        Configuration item read request
        Payload transcribed from the crsf-wg wiki page CRSF_FRAMETYPE_PARAMETER_READ.md
        */
        [ExtendedHeader]
        class PARAMETER_READ {
            // CRSF frame type byte - the source protocol's identity, not this pack's AdHoc id.
            public const int frame_type = 0x2C;
            /**
            0 is the root folder listing the top-level items, real fields start at 1
            */
            byte fieldIndex;
            /**
            chunk of the parameter description to fetch, starting at 0
            */
            byte chunkIndex;
        }

