        // ═════════════════════════ topology ═════════════════════════

        // The RF link between transmitter module and receiver is transparent to CRSF frames, so the demo
        // models the two ends of the conversation: the handset (EdgeTX) and the flight controller.

        // EdgeTX / OpenTX radio with the transmitter module
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Handset : Host { }

        // Betaflight / iNav / ArduPilot behind the receiver
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct FlightController : Host { }

        interface CrsfLink : Connects<Handset, FlightController> {
            // Telemetry items flow from the vehicle to the handset.
            [____________r<(GPS, GPS_TIME, VARIO, BATTERY_SENSOR, BARO_ALTITUDE, AIRSPEED, RPM, TEMP, CELLS, ATTITUDE, FLIGHT_MODE, LINK_RX_ID, LINK_TX_ID)>]
            struct Telemetry { }
            // Channel data flows from the handset to the vehicle.
            [l____________<(RC_CHANNELS_PACKED, SUBSET_RC_CHANNELS_PACKED)>]
            struct Control { }
            // Link statistics, heartbeat and every extended-header frame (ping/info, parameters, commands, MSP tunnel) go both ways.
            [_____lr_____<(HEARTBEAT, LINK_STATISTICS, DEVICE_PING, DEVICE_INFO, PARAMETER_SETTINGS_ENTRY, PARAMETER_READ, PARAMETER_WRITE, ELRS_STATUS, COMMAND, HANDSET, KISS_REQ, KISS_RESP, MSP_REQ, MSP_RESP, MSP_WRITE, ARDUPILOT_RESP, DISPLAYPORT_CMD)>]
            struct Extended { }
        }

